<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount} from 'vue'
import {useRoute} from 'vue-router'
import {ElMessageBox} from 'element-plus'
import {evaluationApi,type EvaluationRun,type EvaluationResult} from '../api'
import {errorMessage,formatDate} from '../utils'
import EvaluationMetrics from '../components/EvaluationMetrics.vue'
const route=useRoute(),pid=Number(route.params.projectId),id=String(route.params.runId),run=ref<EvaluationRun>(),error=ref(''),loading=ref(false),detail=ref<EvaluationResult>(),dialog=ref(false),detailLoading=ref(false),stopping=ref(false)
let timer:ReturnType<typeof setTimeout>|undefined,disposed=false
const names:Record<string,string>={queued:'排队',running:'运行中',stopping:'停止中',completed:'运行结束',succeeded:'成功',partial:'生成成功，Judge 未完成',failed:'失败',interrupted:'中断',not_run:'未开始',skipped:'跳过'}
function active(){return run.value&&['queued','running','stopping'].includes(run.value.status)}
async function load(){if(timer)clearTimeout(timer);loading.value=true;error.value='';try{const value=await evaluationApi.run(pid,id);if(!disposed)run.value=value}catch(e){if(!disposed)error.value=errorMessage(e)}finally{if(!disposed){loading.value=false;if(active())timer=setTimeout(load,1500)}}}
async function show(result:EvaluationResult){dialog.value=true;detail.value=undefined;detailLoading.value=true;try{detail.value=await evaluationApi.result(pid,id,result.id)}catch(e){error.value=errorMessage(e)}finally{detailLoading.value=false}}
async function stop(){try{await ElMessageBox.confirm('停止剩余样本？当前在途调用可能已计费，会在返回后保存已有结果；不再开始后续阶段。','停止评测',{type:'warning',confirmButtonText:'停止剩余样本',cancelButtonText:'继续运行'})}catch{return}stopping.value=true;try{run.value=await evaluationApi.stop(pid,id);void load()}catch(e){error.value=errorMessage(e)}finally{stopping.value=false}}
onMounted(load);onBeforeUnmount(()=>{disposed=true;if(timer)clearTimeout(timer)})
</script>
<template><main><router-link :to="`/projects/${pid}/evaluations`" class="back-link">← 离线评测</router-link><div class="page-heading"><div><div class="eyebrow">EVALUATION RUN</div><h1>{{run?.name||'评测运行'}}</h1><p>{{names[run?.status||'queued']}} · {{run?.finished_count||0}} / {{run?.sample_count||0}} 个样本结束</p></div><div><el-button :loading="loading" @click="load">刷新评测</el-button><el-button v-if="active()" type="danger" plain :loading="stopping" :disabled="run?.status==='stopping'" @click="stop">停止剩余样本</el-button></div></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><template v-if="run"><el-alert v-if="run.config_snapshot.mock_mode" title="Mock 演示：固定模板与固定 Judge 分数，仅验证流程，不能用于判断模型质量。" type="warning" :closable="false"/><el-alert v-if="run.error_message" :title="run.error_message" type="warning" :closable="false"/><p class="field-help">创建 {{formatDate(run.created_at)}} · 完成表示队列处理结束，仍须查看生成和 Judge 的成功率。刷新只读取，不重发模型。</p><EvaluationMetrics :value="run.metrics"/><p class="field-help">标准点词面匹配仅为代理指标；无标准点排除召回分母。有标准点但生成失败仍计入分母。疑似幻觉需人工复核。耗时为阶段合计，费用不估算，Token 缺失标为未知。</p><details><summary>配置 / 模型 / Prompt / Skill / 检索版本快照</summary><pre>{{JSON.stringify(run.config_snapshot,null,2)}}</pre></details><article v-for="result in run.results" :key="result.id" class="case-card"><h3>{{result.position}}. {{result.sample_snapshot.name}}</h3><p>{{names[result.status]||result.status}} · 生成 {{names[result.generation_status]||result.generation_status}} · Judge {{names[result.judge_status]||result.judge_status}} · {{result.case_count}} 条用例</p><p class="field-help">样本 v{{result.sample_snapshot.revision}} · {{result.sample_snapshot.content.gold_points.length}} 个标准点 · ID {{result.sample_id}}</p><el-alert v-if="result.error_message" :title="result.error_message" type="warning" :closable="false"/><p v-if="result.model_call_pending" class="field-help">有模型调用未完整确认；中断/失败不自动重发，重新运行可能重复计费。</p><el-button :disabled="detailLoading" @click="show(result)">查看样本结果</el-button></article></template>
<el-dialog v-model="dialog" title="评测样本结果" width="min(1000px,95vw)"><p v-if="detailLoading">加载中…</p><template v-if="detail"><h3>{{detail.sample_snapshot.name}} · {{names[detail.status]}}</h3><el-alert v-if="detail.error_message" :title="detail.error_message" type="warning" :closable="false"/><details><summary>固定样本输入</summary><pre>{{JSON.stringify(detail.sample_snapshot,null,2)}}</pre></details><article v-for="item in detail.cases" :key="item.case_id" class="case-card"><h4>{{item.fields.title}}</h4><p>用例 ID {{item.case_id}} · {{item.fields.priority}} · {{item.fields.case_type}}</p><dl><dt>前置条件</dt><dd>{{item.fields.precondition||'无'}}</dd><dt>步骤</dt><dd><ol><li v-for="(step,index) in item.fields.steps" :key="index">{{step}}</li></ol></dd><dt>预期</dt><dd>{{item.fields.expected_result}}</dd></dl><p>知识引用 {{item.knowledge_refs.join(', ')||'无'}} · 专项 {{item.skill_refs.join(', ')||'无'}}</p></article><h4>标准点匹配与证据</h4><article v-for="(match,index) in detail.matches" :key="index"><p>{{match.matched?'命中':'未匹配'}} · {{match.point}}</p><pre v-if="match.evidence.length">{{JSON.stringify(match.evidence,null,2)}}</pre></article><p v-if="!detail.matches?.length">未提供标准点或尚未成功生成，不显示匹配结论。</p><details><summary>Judge 报告（仅本次快照）</summary><pre>{{JSON.stringify(detail.judge_report,null,2)}}</pre></details><details><summary>重复提示 / 耗时 / Token</summary><pre>{{JSON.stringify({duplicates:detail.duplicate_findings,timings:detail.timings,usage:detail.usage},null,2)}}</pre></details><details><summary>知识候选 / 排名 / 降级快照</summary><pre>{{JSON.stringify(detail.knowledge,null,2)}}</pre></details><details><summary>实际生成消息与 Judge 输入（不含凭据）</summary><pre>{{JSON.stringify({messages:detail.messages,judge_input:detail.judge_input},null,2)}}</pre></details></template></el-dialog></main></template>
<style scoped>pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:450px;overflow:auto;background:#f5f7fa;padding:12px}details{margin:18px 0}.case-card{margin-top:18px}dd{white-space:pre-wrap;overflow-wrap:anywhere}</style>
